(function() {
  function updateVisibility() {
    const width = window.innerWidth;

    document.querySelectorAll('.BigComputer').forEach(el => {
      el.style.display = (width >= 1900) ? '' : 'none';
    });

    document.querySelectorAll('.Computer').forEach(el => {
      el.style.display = (width < 1900 && width >= 1200) ? '' : 'none';
    });

    document.querySelectorAll('.BigTablet').forEach(el => {
      el.style.display = (width < 1400 && width >= 900) ? '' : 'none';
    });

    document.querySelectorAll('.Tablet').forEach(el => {
      el.style.display = (width < 900 && width >= 500) ? '' : 'none';
    });

    document.querySelectorAll('.Mobile').forEach(el => {
      el.style.display = (width < 1199) ? '' : 'none';
    });
  }

  window.addEventListener('load', updateVisibility);
  window.addEventListener('resize', updateVisibility);
})();
